function countGridColourings(m: number, n: number): number {
  const g: number[][] = Array.from({ length: m }, () => new Array(n).fill(-1));
  const go = (k: number): number => {
    if (k === m * n) return 1;
    const i = k % m, j = Math.floor(k / m);
    let total = 0;
    for (let c = 0; c < 3; c++) {
      if (i > 0 && g[i - 1][j] === c) continue;
      if (j > 0 && g[i][j - 1] === c) continue;
      g[i][j] = c;
      total += go(k + 1);
    }
    g[i][j] = -1;
    return total;
  };
  return go(0) % 1000000007;
}

