function countGridColourings(m: number, n: number): number {
  const MOD = 1000000007;
  const cols: number[][] = [];
  const build = (cur: number[]) => {
    if (cur.length === m) { cols.push(cur.slice()); return; }
    for (let c = 0; c < 3; c++) {
      if (cur.length && cur[cur.length - 1] === c) continue;
      cur.push(c); build(cur); cur.pop();
    }
  };
  build([]);
  const P = cols.length;
  const adj: number[][] = cols.map(a => {
    const list: number[] = [];
    for (let q = 0; q < P; q++) if (a.every((x, i) => x !== cols[q][i])) list.push(q);
    return list;
  });
  let ways = new Array(P).fill(1);
  for (let j = 1; j < n; j++) {
    const next = new Array(P).fill(0);
    for (let p = 0; p < P; p++) {
      for (const q of adj[p]) next[q] = (next[q] + ways[p]) % MOD;
    }
    ways = next;
  }
  return ways.reduce((s, x) => (s + x) % MOD, 0);
}

