            for c in range(3):
                if cur and cur[-1] == c:
                    continue
                cur.append(c)
                build(cur)
                cur.pop()

        build([])
        P = len(cols)
        adj = [[q for q in range(P) if all(x != y for x, y in zip(cols[p], cols[q]))] for p in range(P)]
        ways = [1] * P
        for _ in range(n - 1):
            nxt = [0] * P
            for p in range(P):
                w = ways[p]
                for q in adj[p]:
                    nxt[q] += w
            ways = [x % MOD for x in nxt]
        return sum(ways) % MOD

