function countGridColourings(m: number, n: number): number {
  const MOD = 1000000007;
  const pow = 3 ** (m - 1);
  // profile: base-3 number of the last m cells, oldest cell in the highest digit
  let ways = new Map<number, number>();
  const first = (i: number, code: number, prev: number) => {
    if (i === m) { ways.set(code, 1); return; }
    for (let c = 0; c < 3; c++) if (c !== prev) first(i + 1, code * 3 + c, c);
  };
  first(0, 0, -1);
  for (let j = 1; j < n; j++) {
    for (let i = 0; i < m; i++) {
      const next = new Map<number, number>();
      for (const [code, w] of ways) {
        const left = Math.floor(code / pow); // same row, previous column
        const up = code % 3;                  // previous cell in this column
        const rest = code % pow;
        for (let c = 0; c < 3; c++) {
          if (c === left || (i > 0 && c === up)) continue;
          const key = rest * 3 + c;
          next.set(key, ((next.get(key) || 0) + w) % MOD);
        }
      }
      ways = next;
    }
  }
  let total = 0;
  for (const w of ways.values()) total = (total + w) % MOD;
  return total;
}

