                if c != prev:
                    first(i + 1, code * 3 + c, c)

        first(0, 0, -1)
        for _ in range(n - 1):
            for i in range(m):
                nxt = defaultdict(int)
                for code, w in ways.items():
                    left, up, rest = code // pw, code % 3, code % pw
                    for c in range(3):
                        if c == left or (i > 0 and c == up):
                            continue
                        nxt[rest * 3 + c] += w
                ways = {k: v % MOD for k, v in nxt.items()}
        return sum(ways.values()) % MOD

